function portrait(t){if(t.siegeStyle)return siegePortrait(t);const color=t.color,accent=t.accent||'#ffda78',weapon=t.weapon;
 if(weapon==='cannon'||weapon==='catapult')return '<svg viewBox="0 0 120 110"><ellipse cx="63" cy="100" rx="45" ry="5" fill="#0003"/>'+(weapon==='catapult'?'<path d="M30 91L54 40L86 91M54 40L99 14" fill="none" stroke="#a68c61" stroke-width="9"/><path d="M91 11h22v8H91" fill="#baa577"/>':'<path d="M23 78L103 65L105 81L30 93Z" fill="#746642"/><path d="M25 61L106 47L111 67L31 82Z" fill="#a98a4f" stroke="#d9bc73" stroke-width="2"/><ellipse cx="108" cy="57" rx="6" ry="11" fill="#3a3b2a" stroke="#bfa164" stroke-width="4"/>')+'<circle cx="43" cy="90" r="17" fill="#4a4837" stroke="#af9562" stroke-width="4"/><path d="M43 74v32M27 90h32M32 79l23 23M32 101l23-23" stroke="#ad925d" stroke-width="2"/><circle cx="88" cy="86" r="12" fill="#58503a" stroke="#b49a60" stroke-width="3"/></svg>';
 const helmet=uniformSvg(t,'head');
 let gear=weapon==='axe'?'<path d="M87 99L93 21" stroke="#b99560" stroke-width="5"/><path d="M92 23L111 15L114 38L93 44Z" fill="#b5c7cc" stroke="#e1e7d8"/>':weapon==='javelin'?'<path d="M83 95L106 17" stroke="#b99560" stroke-width="4"/><path d="M101 20L111 5L111 23Z" fill="#d9e4da"/>':weapon==='bow'?'<path d="M96 36Q119 66 95 94" fill="none" stroke="#dab87b" stroke-width="4"/><path d="M96 36v58" stroke="#e8d6a3"/><path d="M79 58l29 2" stroke="#d6cfb3" stroke-width="2"/>':weapon==='crossbow'?'<path d="M80 81L100 46" stroke="#80633d" stroke-width="7"/><path d="M79 51Q103 37 115 58" fill="none" stroke="#c9bd9b" stroke-width="4"/><path d="M79 51L115 58" stroke="#d7c5a6"/>':weapon==='bomb'||weapon==='firepot'?'<circle cx="88" cy="62" r="10" fill="'+(weapon==='firepot'?'#a57b49':'#353d36')+'"/><path d="M89 52q9-11 14-4" stroke="#c6a768" fill="none"/><circle cx="102" cy="48" r="3" fill="#edc476"/>':weapon==='shield'?'<path d="M77 51l23 6v20q-3 15-15 19Q73 86 73 74Z" fill="#adb2a0" stroke="#ded7b2" stroke-width="2"/><path d="M86 56v31" stroke="#556759"/>':weapon==='spear'?'<path d="M91 95L99 10" stroke="#b69b68" stroke-width="4"/><path d="M93 15L100 0L105 17Z" fill="#d8d6bb"/>':weapon==='gun'?'<path d="M76 70L105 39" stroke="#454a3e" stroke-width="7"/><path d="M80 64L101 43" stroke="#b4b7a4" stroke-width="3"/>':weapon==='drum'?'<ellipse cx="70" cy="83" rx="22" ry="16" fill="#bd945e" stroke="#e2c68e" stroke-width="3"/><path d="M49 65l27 14M83 59L66 77" stroke="#d7b16d" stroke-width="3"/>':weapon==='banner'?'<path d="M91 100V12" stroke="#c9ae75" stroke-width="4"/><path d="M93 14h24l-3 26H93Z" fill="'+color+'" stroke="#e5cea2"/><path d="M100 26a5 5 0 1 0 10 0a5 5 0 1 0-10 0" fill="none" stroke="#e9d7ad" stroke-width="2"/>':weapon==='pick'?'<path d="M88 39v64" stroke="#b39563" stroke-width="5"/><path d="M74 36q13-12 28 2" fill="none" stroke="#b7c2ab" stroke-width="5"/>':'<path d="M92 73l12-47" stroke="#d9d5bd" stroke-width="4"/><path d="M87 71l13 4" stroke="#bd9b5f" stroke-width="3"/>';
 const horse=t.mounted?'<ellipse cx="57" cy="86" rx="36" ry="16" fill="#695640"/><path d="M80 84L95 51L108 56L97 84" fill="#695640"/><path d="M33 88l-7 22M78 88l8 22" stroke="#67563e" stroke-width="8"/><path d="M89 57l16 7" stroke="#d1b477" stroke-width="3"/>':'';
 return '<svg viewBox="0 0 120 110"><ellipse cx="61" cy="106" rx="36" ry="4" fill="#0003"/>'+horse+'<g '+(t.mounted?'transform="translate(-6,-6) scale(.85)"':'')+'><path d="M48 83l-4 25h13l5-25M65 83l3 25h13l-6-25" fill="'+uniformParts(t).pants+'"/>'+uniformSvg(t,'body')+'<path d="M36 77l-2 10" stroke="#bd966f" stroke-width="7"/><path d="M86 70l10-7" stroke="#c39d78" stroke-width="7"/><ellipse cx="61" cy="34" rx="14" ry="16" fill="#c7a37e"/><path d="M48 37q11 17 25 1-4 20-15 16Z" fill="#504637"/>'+helmet+gear+'</g></svg>';
}
function drawNationFlags(){const map=currentMap().id,own=currentNation(1),foe=currentNation(-1);const flags=map==='istanbul'?[[137,202,own],[1316,156,foe]]:map==='vienna'?[[140,227,own],[1353,172,foe]]:[[140,227,own],[1323,216,foe]];for(const [x,y,n] of flags){poly([[x,y],[x+44,y+5],[x+40,y+35],[x,y+32]],n.color);ctx.fillStyle=n.accent;ctx.font='24px Georgia';ctx.textAlign='center';ctx.fillText(n.symbol,x+21,y+25);ctx.textAlign='left'}}
